/**
 * Utility functions for user onboarding detection
 */
import { normalizeEmail } from "./verified-email";

export function hasCompletedOnboarding(
  username: string | null | undefined,
  member: { onboardingStatus: string; email: string | null } | undefined,
  verifiedEmail: string | null,
): boolean {
  return (
    !needsOnboarding(username) &&
    member?.onboardingStatus === "completed" &&
    !!member.email &&
    !!verifiedEmail &&
    normalizeEmail(member.email) === verifiedEmail
  );
}

/**
 * Checks if a username appears to be auto-generated
 * The entire legacy user_ prefix is reserved, regardless of suffix or case.
 */
export function isAutoGeneratedUsername(
  username: string | null | undefined,
): boolean {
  if (!username) return true;

  return /^user_/i.test(username.trim());
}

/**
 * Determines if a user needs to complete onboarding
 * A user needs onboarding if:
 * - They have no username (null)
 * - They have an auto-generated username
 */
export function needsOnboarding(username: string | null | undefined): boolean {
  return !username || isAutoGeneratedUsername(username);
}

/**
 * Validates username format
 * Requirements:
 * - 3-30 characters
 * - Letters, numbers, underscores, hyphens only
 * - Must start with a letter or number
 */
export function validateUsernameFormat(username: string): {
  valid: boolean;
  error?: string;
} {
  if (!username || username.trim().length === 0) {
    return { valid: false, error: "Username is required" };
  }

  const trimmed = username.trim();

  if (trimmed.length < 3) {
    return { valid: false, error: "Username must be at least 3 characters" };
  }

  if (trimmed.length > 30) {
    return { valid: false, error: "Username must be less than 30 characters" };
  }

  // Must start with letter or number, can contain letters, numbers, underscores, hyphens
  const validPattern = /^[a-zA-Z0-9][a-zA-Z0-9_-]*$/;
  if (!validPattern.test(trimmed)) {
    return {
      valid: false,
      error:
        "Username must start with a letter or number and contain only letters, numbers, underscores, or hyphens",
    };
  }

  // Reserve all legacy placeholder names, including manually chosen variants.
  if (isAutoGeneratedUsername(trimmed)) {
    return {
      valid: false,
      error:
        "Usernames starting with user_ are reserved. Please choose another username.",
    };
  }

  return { valid: true };
}
